import type { AgentTeamProjectRef, AgentTeamThreadReadFact, AgentTeamThreadRef } from './types/entities.ts'
import type { AgentTeamInboxItem, AgentTeamInboxReminder, AgentTeamMainTimelineEntry } from './types/requests-results.ts'

/** Ordinary Thread updates an owner accumulates per Thread before they interrupt it; a runtime parameter, never stored. */
export const INBOX_THRESHOLD_UPDATES = 5

export type InboxDelivery = 'immediate' | 'threshold'

/** The reader's role in one notice scope, as the notice states it. */
export type InboxScopeRole = 'owner' | 'follower' | 'member'

export interface InboxThreadUnread {
  readonly item: AgentTeamInboxItem
  readonly facts: readonly AgentTeamThreadReadFact[]
  readonly reminders?: readonly AgentTeamInboxReminder[]
}

export interface InboxMainUnread {
  readonly projectRef: AgentTeamProjectRef
  readonly entries: readonly AgentTeamMainTimelineEntry[]
}

export interface InboxDeliveryInput {
  readonly threads: readonly InboxThreadUnread[]
  readonly main: readonly InboxMainUnread[]
  readonly owns: (projectRef: AgentTeamProjectRef) => boolean
  /** Newest ordinary sequence each Thread's threshold updates were last delivered through. */
  readonly summarizedThrough: ReadonlyMap<AgentTeamThreadRef, number>
  /** Signature of the immediate facts the last delivery attempt answered. */
  readonly covered: string | undefined
}

export interface InboxThreadPlan {
  readonly threadRef: AgentTeamThreadRef
  readonly role: InboxScopeRole
  readonly delivery: InboxDelivery
  /** Ordinary facts that wait for the threshold; zero unless the reader owns the Project. */
  readonly thresholdCount: number
}

export interface InboxDeliveryPlan {
  /** Why a notice goes out now, or `undefined` when nothing may interrupt the reader. */
  readonly trigger: InboxDelivery | undefined
  readonly signature: string
  /** `summarizedThrough` as it stands once this plan's notice is delivered. */
  readonly summarizedThrough: ReadonlyMap<AgentTeamThreadRef, number>
  readonly threads: readonly InboxThreadPlan[]
}

function isThresholdFact(entry: AgentTeamThreadReadFact, owner: boolean): boolean {
  return owner && entry.fact.kind === 'message' && !entry.direct
}

/**
 * Decide whether the reader's current unread interrupts it. Mentions, replies to the reader, activities, Main stream unread and
 * a non-owner follower's ordinary updates are immediate; an owner's ordinary Thread updates wait until one Thread holds
 * `INBOX_THRESHOLD_UPDATES` undelivered ones, and otherwise ride along with the next immediate notice.
 */
export function planInboxDelivery(input: InboxDeliveryInput): InboxDeliveryPlan {
  const immediate: (string | number)[][] = []
  const summarizedThrough = new Map<AgentTeamThreadRef, number>()
  const threads: InboxThreadPlan[] = []
  let thresholdReached = false
  for (const { item, facts, reminders = [] } of input.threads) {
    const threadRef = item.thread.threadRef
    if (reminders.length > 0) immediate.push([threadRef, 'reminder', ...reminders.map(reminder => `${reminder.kind}:${reminder.baselineSequence}`)])
    const owner = input.owns(item.projectRef)
    const waiting = facts.filter(entry => isThresholdFact(entry, owner))
    const now = facts.filter(entry => !isThresholdFact(entry, owner)).map(entry => entry.fact.sequence)
    if (now.length > 0) immediate.push([threadRef, ...now])
    const through = input.summarizedThrough.get(threadRef) ?? 0
    if (waiting.filter(entry => entry.fact.sequence > through).length >= INBOX_THRESHOLD_UPDATES) thresholdReached = true
    if (waiting.length > 0) summarizedThrough.set(threadRef, waiting.at(-1)!.fact.sequence)
    threads.push(Object.freeze({ threadRef, role: owner ? 'owner' : item.attention === undefined ? 'member' : 'follower',
      delivery: now.length > 0 || reminders.length > 0 ? 'immediate' : 'threshold', thresholdCount: waiting.length }))
  }
  for (const { projectRef, entries } of input.main) {
    if (entries.length > 0) immediate.push([projectRef, ...entries.map(entry => entry.sequence)])
  }
  const signature = immediate.length === 0 ? '' : JSON.stringify(immediate)
  const trigger = signature !== '' && signature !== input.covered ? 'immediate' : thresholdReached ? 'threshold' : undefined
  return Object.freeze({ trigger, signature, summarizedThrough, threads: Object.freeze(threads) })
}

startThread(request: AgentTeamAuthorizedStartThreadRequest): Promise<AgentTeamLedgerResult<AgentTeamStartThreadResult>> {
  return this.enqueue(async () => {
    const actor = this.assertActorForWorkspace(request.actor, request.workspaceId)
    const project = this.requireActiveProject(request.workspaceId, request.projectRef)
    const body = request.body.trim()
    if (body === '') throw new Error('message body must not be empty')
    const recipients = this.mergeBodyMentions(actor.memberId, project.projectRef, body, this.normalizeRecipients(actor, request.recipients))
    const existing = this.state.byRequest.get(request.requestId)
    if (existing !== undefined) {
      this.assertSameThreadStart(existing, request, recipients)
      return this.resolved(this.startThreadResult(existing))
    }
    this.requireRulesVersion2('starting a Thread')
    this.requireProjectMemberActor(actor, project.projectRef)
    this.requireProjectOwnerActor(actor, project.projectRef)
    this.assertMentionTargets(project, recipients)
    const sequence = this.nextSequence()
    const base = this.operationBase(request, sequence)
    const threadRef = this.ref('thread')
    const taskRef = request.kind === 'task' ? this.ref('task') : undefined
    if (request.kind === 'task' && actor.kind === 'member' && request.accountable !== undefined && request.accountable !== actor.memberId) {
      throw new Error(`An Agent names itself accountable when starting a Task (accountable_target_invalid) — ${recoveryFor('accountable_target_invalid').sentence({})}`)
    }
    const accountable = request.kind === 'task' ? this.resolveAccountable(project.projectRef, actor, request.accountable) : undefined
    if (request.kind !== 'task' && (request.accountable !== undefined || request.sourceThreadRefs !== undefined)) throw new Error('only a Task accepts accountable and sourceThreadRefs')
    const sourceThreadRefs = request.kind === 'task' ? this.validateTaskSources(project.projectRef, request.sourceThreadRefs) : []
    const task = taskRef === undefined || accountable === undefined ? undefined
      : Object.freeze({ taskRef, projectRef: project.projectRef, threadRef, status: 'todo' as const, resolution: 'open' as const, accountable, sourceThreadRefs })
    const taskActivity = task === undefined ? undefined : Object.freeze({ activityRef: this.ref('activity'), kind: 'promote' as const,
      taskRef: task.taskRef, threadRef, actor: actor.memberId, sequence })
    const thread: AgentTeamThread = Object.freeze({ threadRef, ...(taskRef === undefined ? {} : { taskRef }), revision: sequence })
    const anchor: AgentTeamMessage = Object.freeze({
      messageRef: this.ref('message'), projectRef: project.projectRef, threadRef, ...(taskRef === undefined ? {} : { taskRef }),
      sender: actor.memberId, body,
      ...(request.resolvedAttachments === undefined ? {} : { attachments: request.resolvedAttachments }),
      topLevel: true, sequence, occurredAt: base.occurredAt,
    })
    const inbox = taskActivity === undefined
      ? this.messageInboxDelta(anchor, actor.memberId, recipients, [this.startAttention(actor.memberId, threadRef, sequence)])
      : this.inboxDeltaForTaskResponsibility(this.state, task!, taskActivity, anchor, recipients)
    const operation: AgentTeamThreadStartedOperation = Object.freeze({
      ...base, kind: 'team/thread-started',
      data: Object.freeze({ workspaceId: request.workspaceId, projectRef: project.projectRef, kind: request.kind, mentions: recipients,
        anchor, ...(task === undefined ? {} : { task }), ...(taskActivity === undefined ? {} : { activity: taskActivity }), thread, inbox }),
    })
    await this.table.put(operation.operationId, operation)
    this.applyAndAdvanceProjectionVersion(operation)
    return this.committed(this.startThreadResult(operation))
  })
}

/** One page of a Project's Main stream, oldest first, with the reader's own standing. Never writes. */
mainStreamHistory(actor: AgentTeamHumanActor | AgentTeamMemberActor, request: AgentTeamMainStreamHistoryRequest): AgentTeamMainStreamHistory {
  this.requireRulesVersion2('the Main stream')
  const authorized = this.assertActorForWorkspace(actor, request.workspaceId)
  const project = this.requireActiveProject(request.workspaceId, request.projectRef)
  this.requireProjectMemberActor(authorized, project.projectRef)
  const limit = request.limit ?? 20
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error('history limit must be an integer between 1 and 100')
  const sources = this.mainSourcesFrom(this.state, project.projectRef).filter(source => source.kind !== 'thread' || source.hidden !== true)

