import { afterEach, describe, expect, it, vi } from 'vitest'
import { Context } from '@deepseek-ai/cordis'
import Storage from '@deepseek-ai/dsh-storage'
import SessionProjectionRegistry from '@deepseek-ai/dsh-session-projection'
import { DomainFacility } from '@deepseek-ai/dsh-storage-domain'
import { SessionId } from '@deepseek-ai/dsh-session'
import { WorkspaceId } from '@deepseek-ai/dsh-workspace'
import { provideQuietTokenMeter } from '../../packages/agent-team/tests/helpers/team-host-fixture.ts'
import { MemoryMediaPool, MemoryStorageBackend } from '../../packages/agent-team/tests/helpers/memory-backend.ts'
import AgentTeam from '../../packages/agent-team/src/index.ts'
import { agentTeamHumanActor } from '../../packages/agent-team/src/ledger.ts'
import * as agentTeamInvariant from '../../packages/agent-team/src/invariant.ts'
import type { Agent } from '@deepseek-ai/dsh-agent'
import type { UserMessage } from '@deepseek-ai/dsh-llm'
import type { AgentTeamProjectRef, AgentTeamMemberActor, AgentTeamRequestId } from '../../packages/agent-team/src/types.ts'

const cleanups: Array<() => Promise<void>> = []
const alpha = WorkspaceId('workspace:alpha')
const requestId = (value: string): AgentTeamRequestId => value as AgentTeamRequestId

afterEach(async () => {
  await Promise.all(cleanups.splice(0).map(cleanup => cleanup()))
})

async function harness(): Promise<{ readonly ctx: Context }> {
  const ctx = new Context()
  await ctx.plugin(Storage)
  ctx.storage.backend.register('memory', new MemoryStorageBackend(new MemoryMediaPool()))
  const facility = new DomainFacility(ctx, { backend: 'memory', routes: {} })
  ctx.storage.mount('domain', facility)
  ctx.provide('storageDomain', facility)
  ctx.provide('workspaceRegistry', {
    get: (id: WorkspaceId) => id === alpha ? { id, path: process.cwd(), attachSession: async () => {}, archiveSession: async () => {} } : undefined,
    list: () => [{ id: alpha, path: process.cwd() }],
    archiveSession: async () => {},
  })
  ctx.provide('agents', { create: async () => { throw new Error('unused') }, resume: async () => { throw new Error('unused') } })
  ctx.provide('agentDefaultModel', { currentSelection: () => ({ provider: 'mock', model: 'mock' }) })
  ctx.provide('agentPresets', { mount: async () => { throw new Error('unused') } })
  ctx.provide('tools', { schemas: () => [] })
  ctx.provide('sessionPersistence', { list: async () => [] })
  provideQuietTokenMeter(ctx)
  await ctx.plugin(agentTeamInvariant)
  await ctx.plugin(SessionProjectionRegistry)
  const fiber = await ctx.plugin(AgentTeam)
  cleanups.push(async () => { await fiber.dispose(); await facility.closeAll() })
  return { ctx }
}

async function addLiveMember(ctx: Context, projectRef: AgentTeamProjectRef, handle = 'reader'): Promise<AgentTeamMemberActor> {
  const memberId = `member:agent-${crypto.randomUUID()}` as AgentTeamMemberActor['memberId']
  await ctx.agentTeam['ledger']!.addMember({
    requestId: requestId(`ledger-member-${memberId}`), workspaceId: alpha, handle, description: 'Reads work', presetId: 'team-member',
    projectRefs: [projectRef], actor: agentTeamHumanActor(),
    member: {
      memberId, sessionId: SessionId(`session:${memberId}`), workspaceId: alpha, handle, description: 'Reads work',
      presetId: 'team-member', privateMemoryPath: '/tmp/reader', state: 'enabled' as const,
    },
  })
  return { kind: 'member', memberId, handle }
}

function wakeSeam(): { readonly agent: Agent; readonly state: { fail: boolean; readonly calls: UserMessage[] } } {
  const state = { fail: false, calls: [] as UserMessage[] }
  const wake = (message: UserMessage): void => { state.calls.push(message) }
  const agent = {
    id: SessionId('session:owner-task-followup'),
    status: 'idle',
    inbox: { nextTurn: [], nextStep: [], remove: () => {} },
    steer: wake,
    followup: wake,
  } as unknown as Agent
  return { agent, state }
}

describe('an owner who creates a Task Thread', () => {
  it('IS interrupted by the ordinary Thread updates on the Task it created', async () => {
    const { ctx } = await harness()
    const project = await ctx.agentTeam.createProject({ requestId: requestId('p'), workspaceId: alpha, name: 'engineering', description: 'Engineering' })
    const projectRef = project.project.projectRef
    const member = await addLiveMember(ctx, projectRef)
    await ctx.agentTeam.addProjectOwner({ requestId: requestId('own'), workspaceId: alpha, projectRef, memberId: member.memberId })
    const ledger = ctx.agentTeam['ledger']!

    // The owner starts a Task Thread for itself (accountable defaults to the actor).
    const started = await ledger.startThread({ requestId: requestId('start'), actor: member, workspaceId: alpha, projectRef,
      kind: 'task', body: 'Build the gateway' })
    if (started.value.kind !== 'committed') throw new Error('expected a committed start')

    const { agent, state } = wakeSeam()
    ctx.agentTeam['handles'].set(member.memberId, { agent, dispose: async () => {} })

    // Another member replies in the Thread five times.
    const other = await addLiveMember(ctx, projectRef, 'other')
    let revision = started.value.thread.revision
    for (let index = 1; index <= 5; index += 1) {
      const result = await ctx.agentTeam.reply({ requestId: requestId(`r-${index}`), workspaceId: alpha,
        threadRef: started.value.thread.threadRef, body: `update ${index}`, baseRevision: revision })
      if (result.kind !== 'committed') throw new Error('expected a committed reply')
      revision = result.thread.revision
    }

    const notices = state.calls.map(call => call.content[0])
    const texts = notices.map(n => (n as { text: string }).text)
    console.log('NOTICE COUNT:', notices.length)
    console.log('NOTICE TEXTS:', JSON.stringify(texts, null, 2))

    // Owner-created Task Thread: does it receive the threshold notice at all?
    expect(state.calls).toHaveLength(1)
  })
})

