  await ctx.agentTeam['ledger']!.addMember({
    requestId: requestId(`ledger-member-${handle}-${memberId}`), workspaceId: alpha, handle, description: 'Reads work', presetId: 'team-member',
    projectRefs: [projectRef], actor: agentTeamHumanActor(),
    member: {
      memberId, sessionId: SessionId(`session:${handle}-${memberId}`), workspaceId: alpha, handle, description: 'Reads work',
      presetId: 'team-member', privateMemoryPath: `/tmp/${handle}`, state: 'enabled' as const,
    },
