async function replyTimes(ctx: Context, threadRef: string, revisionStart: number, times: number, member: AgentTeamMemberActor, tag: string): Promise<number> {
  let revision = revisionStart
  for (let index = 1; index <= times; index += 1) {
    const result = await ctx.agentTeam.reply({ requestId: requestId(`${tag}-${index}`), workspaceId: alpha,
      threadRef: threadRef as never, body: `${tag} ${index}`, baseRevision: revision, actor: undefined as never })
    if (result.kind !== 'committed') throw new Error(`expected a committed reply, got ${result.kind}`)
    revision = result.thread.revision
  }
  return revision
}

