describe('does a Task Thread creator keep receiving the Thread?', () => {
  it('A: owner creates a Task accountable to itself, another member replies five times', async () => {
    const { ctx } = await harness()
    const project = await ctx.agentTeam.createProject({ requestId: requestId('a-p'), workspaceId: alpha, name: 'engineering', description: 'Engineering' })
    const projectRef = project.project.projectRef
    const owner = await addLiveMember(ctx, projectRef, 'owner-a')
    await ctx.agentTeam.addProjectOwner({ requestId: requestId('a-own'), workspaceId: alpha, projectRef, memberId: owner.memberId })
    const other = await addLiveMember(ctx, projectRef, 'other-a')
    const ledger = ctx.agentTeam['ledger']!

    const started = await ledger.startThread({ requestId: requestId('a-start'), actor: owner, workspaceId: alpha, projectRef,
      kind: 'task', body: 'Build the gateway' })
    if (started.value.kind !== 'committed') throw new Error('expected a committed start')

    const ownerSeam = wakeSeam('owner-a')
    const otherSeam = wakeSeam('other-a')
    ctx.agentTeam['handles'].set(owner.memberId, { agent: ownerSeam.agent, dispose: async () => {} })
    ctx.agentTeam['handles'].set(other.memberId, { agent: otherSeam.agent, dispose: async () => {} })

    await replyTimes(ctx, started.value.thread.threadRef, started.value.thread.revision, 5, other, 'a-reply')
    report('A owner (accountable=self) after 5 replies from another member', ownerSeam.state)
    report('A other member (non-owner follower) after 5 replies', otherSeam.state)
  })

  it('B: owner creates a Task accountable to a different owner, a third member replies five times', async () => {
    const { ctx } = await harness()
    const project = await ctx.agentTeam.createProject({ requestId: requestId('b-p'), workspaceId: alpha, name: 'engineering', description: 'Engineering' })
    const projectRef = project.project.projectRef
    const creator = await addLiveMember(ctx, projectRef, 'creator-b')
    await ctx.agentTeam.addProjectOwner({ requestId: requestId('b-own1'), workspaceId: alpha, projectRef, memberId: creator.memberId })
    const accountable = await addLiveMember(ctx, projectRef, 'accountable-b')
    await ctx.agentTeam.addProjectOwner({ requestId: requestId('b-own2'), workspaceId: alpha, projectRef, memberId: accountable.memberId })
    const worker = await addLiveMember(ctx, projectRef, 'worker-b')
    const ledger = ctx.agentTeam['ledger']!

    const started = await ledger.startThread({ requestId: requestId('b-start'), actor: creator, workspaceId: alpha, projectRef,
      kind: 'task', body: 'Ship the pipeline', accountable: accountable.memberId })
    if (started.value.kind !== 'committed') throw new Error('expected a committed start')

    const creatorSeam = wakeSeam('creator-b')
    const accountableSeam = wakeSeam('accountable-b')
    const workerSeam = wakeSeam('worker-b')
    ctx.agentTeam['handles'].set(creator.memberId, { agent: creatorSeam.agent, dispose: async () => {} })
    ctx.agentTeam['handles'].set(accountable.memberId, { agent: accountableSeam.agent, dispose: async () => {} })
    ctx.agentTeam['handles'].set(worker.memberId, { agent: workerSeam.agent, dispose: async () => {} })

    await replyTimes(ctx, started.value.thread.threadRef, started.value.thread.revision, 5, worker, 'b-reply')
    report('B creator owner after 5 replies from a third member', creatorSeam.state)
    report('B accountable owner after 5 replies', accountableSeam.state)
    report('B worker (non-owner follower) after 5 replies', workerSeam.state)
  })

  it('C: owner creates a Task accountable to itself, then a member mentions it directly', async () => {
    const { ctx } = await harness()
    const project = await ctx.agentTeam.createProject({ requestId: requestId('c-p'), workspaceId: alpha, name: 'engineering', description: 'Engineering' })
    const projectRef = project.project.projectRef
    const owner = await addLiveMember(ctx, projectRef, 'owner-c')
    await ctx.agentTeam.addProjectOwner({ requestId: requestId('c-own'), workspaceId: alpha, projectRef, memberId: owner.memberId })
