async function replyAs(ctx: Context, threadRef: string, revisionStart: number, times: number, member: AgentTeamMemberActor, tag: string): Promise<number> {
  const ledger = ctx.agentTeam['ledger']!
  let revision = revisionStart
  for (let index = 1; index <= times; index += 1) {
    // A writer with unread work is gated until it reads; drain it first.
    let result = await ledger.reply({ requestId: requestId(`${tag}-${index}`), actor: member,
      workspaceId: alpha, threadRef: threadRef as never, body: `${tag} ${index}`, baseRevision: revision })
    while (result.value.kind === 'unread_required') {
      const read = await ledger.readThread({ requestId: requestId(`${tag}-${index}-read`), actor: member, workspaceId: alpha, threadRef })
      revision = read.value.thread.revision
      result = await ledger.reply({ requestId: requestId(`${tag}-${index}`), actor: member,
        workspaceId: alpha, threadRef: threadRef as never, body: `${tag} ${index}`, baseRevision: revision })
    }
    if (result.value.kind !== 'committed') throw new Error(`expected a committed reply, got ${result.value.kind}`)
    // Replay the commit through the Host so its post-commit delivery runs.
    if (result.value.receipt !== undefined) ctx.agentTeam['emitCommitted'](result.value.receipt)
    revision = result.value.thread.revision
  }
