body = '''describe('the creator of a Task Thread', () => {
  /** One Project with an Agent owner plus extra members; the owner's Main stream is drained so only Thread facts stay unread. */
  async function setup(tag: string, handles: readonly string[]): Promise<{
    readonly ctx: Context
    readonly projectRef: AgentTeamProjectRef
    readonly ledger: AgentTeamLedger
    readonly owner: AgentTeamMemberActor
    readonly seams: Record<string, { readonly calls: readonly UserMessage[] }>
    readonly actors: Record<string, AgentTeamMemberActor>
  }> {
    const { ctx } = await harness()
    const project = await ctx.agentTeam.createProject({ requestId: requestId(`${tag}-p`), workspaceId: alpha, name: 'engineering', description: 'Engineering' })
    const projectRef = project.project.projectRef
    const ledger = ctx.agentTeam['ledger']!
    const seams: Record<string, { readonly calls: readonly UserMessage[] }> = {}
    const actors: Record<string, AgentTeamMemberActor> = {}
    const register = async (handle: string): Promise<AgentTeamMemberActor> => {
      const member = await addLiveMember(ctx, projectRef, handle)
      const seam = wakeSeam(`${tag}-${handle}`)
      seams[handle] = seam.state
      actors[handle] = member
      ctx.agentTeam['handles'].set(member.memberId, { agent: seam.agent, dispose: async () => {} })
      return member
    }
    const owner = await register('owner')
    await ctx.agentTeam.addProjectOwner({ requestId: requestId(`${tag}-own`), workspaceId: alpha, projectRef, memberId: owner.memberId })
    // Drain the ownership-grant Main stream marker: the only unread left for the owner is the Thread's own.
    const drained = await ledger.readMainStream({ requestId: requestId(`${tag}-drain`), actor: owner, workspaceId: alpha, projectRef })
    if (!drained.committed) throw new Error('drain did not commit')
    for (const handle of handles) await register(handle)
    return { ctx, projectRef, ledger, owner, seams, actors }
  }

  it('follows its own Task and is interrupted at the fifth ordinary update, then summarized once', async () => {
    const { ctx, projectRef, ledger, owner, seams, actors } = await setup('a', ['worker'])
    const started = await ledger.startThread({ requestId: requestId('a-start'), actor: owner, workspaceId: alpha, projectRef,
      kind: 'task', body: 'Build the gateway' })
    if (started.value.kind !== 'committed') throw new Error('expected a committed start')
    ctx.agentTeam['emitCommitted'](started.value.receipt)
    // The creator holds Attention on its own Thread — it is a follower of what it started.
    expect(ledger.attentionStatus(owner, { workspaceId: alpha, threadRef: started.value.thread.threadRef }).attention).toBeDefined()
    seams['owner']!.calls.length = 0

    await replyAs(ctx, started.value.thread.threadRef, started.value.thread.revision, 4, actors['worker']!, 'a-reply')
    expect(seams['owner']!.calls).toHaveLength(0)
    await replyAs(ctx, started.value.thread.threadRef, started.value.thread.revision, 1, actors['worker']!, 'a-fifth')
    expect(seams['owner']!.calls).toHaveLength(1)
    const notice = (seams['owner']!.calls[0]!.content[0] as { text: string }).text
    expect(notice).toContain('Your role: owner of this Project')
    expect(notice).toContain('Delivery: threshold — 5 ordinary update(s)')
    // A sixth update does not re-interrupt: the summary already covers the first five.
    await replyAs(ctx, started.value.thread.threadRef, started.value.thread.revision, 1, actors['worker']!, 'a-sixth')
    expect(seams['owner']!.calls).toHaveLength(1)
  })

  it('is interrupted immediately by a mention, which carries the waiting ordinary updates along', async () => {
    const { ctx, projectRef, ledger, owner, seams, actors } = await setup('b', ['worker'])
    const started = await ledger.startThread({ requestId: requestId('b-start'), actor: owner, workspaceId: alpha, projectRef,
      kind: 'task', body: 'Audit the schema' })
    if (started.value.kind !== 'committed') throw new Error('expected a committed start')
    ctx.agentTeam['emitCommitted'](started.value.receipt)
    seams['owner']!.calls.length = 0

    await replyAs(ctx, started.value.thread.threadRef, started.value.thread.revision, 1, actors['worker']!, 'b-reply')
    expect(seams['owner']!.calls).toHaveLength(0)
    const mention = await ledger.reply({ requestId: requestId('b-mention'), actor: actors['worker']!, workspaceId: alpha,
      threadRef: started.value.thread.threadRef, body: '@owner please take a look', baseRevision: started.value.thread.revision + 1,
      recipients: [owner.memberId] })
    if (mention.value.kind !== 'committed') throw new Error('expected a committed mention')
    ctx.agentTeam['emitCommitted'](mention.value.receipt)
    expect(seams['owner']!.calls).toHaveLength(1)
    expect((seams['owner']!.calls[0]!.content[0] as { text: string }).text).toContain('Delivery: immediate; 1 ordinary update(s) ride along')
  })

  it('is woken by the Task activity when the Human starts a Task naming it accountable', async () => {
    const { ctx, projectRef, ledger, owner, seams } = await setup('c', ['worker'])
    const started = await ledger.startThread({ requestId: requestId('c-start'), actor: agentTeamHumanActor(), workspaceId: alpha, projectRef,
      kind: 'task', body: 'Ship the pipeline', accountable: owner.memberId })
    if (!started.committed) throw new Error('expected a committed start')
    ctx.agentTeam['emitCommitted'](started.value.receipt)
    expect(seams['owner']!.calls).toHaveLength(1)
    const notice = (seams['owner']!.calls[0]!.content[0] as { text: string }).text
    expect(notice).toContain('Delivery: immediate')
    expect(notice).toContain('Team Task update')
  })

  it('stops receiving ordinary updates once it unfollows its own Task', async () => {
    const { ctx, projectRef, ledger, owner, seams, actors } = await setup('d', ['worker'])
    const started = await ledger.startThread({ requestId: requestId('d-start'), actor: owner, workspaceId: alpha, projectRef,
      kind: 'task', body: 'Hand this over' })
    if (started.value.kind !== 'committed') throw new Error('expected a committed start')
    ctx.agentTeam['emitCommitted'](started.value.receipt)
    seams['owner']!.calls.length = 0

    const unfollowed = await ledger.changeAttention({ requestId: requestId('d-unfollow'), actor: owner, workspaceId: alpha,
      threadRef: started.value.thread.threadRef, action: 'unfollow' })
    if (!unfollowed.committed) throw new Error('expected a committed unfollow')
    ctx.agentTeam['emitCommitted'](unfollowed.value.receipt)
    expect(ledger.attentionStatus(owner, { workspaceId: alpha, threadRef: started.value.thread.threadRef }).attention).toBeUndefined()

    await replyAs(ctx, started.value.thread.threadRef, started.value.thread.revision, 5, actors['worker']!, 'd-reply')
    expect(seams['owner']!.calls).toHaveLength(0)
  })
})
'''
