  it('GAP 1: an owner that claims the Task and does the work is still threshold-batched for Thread messages', async () => {
    const { ctx, projectRef, ledger, owner, seams, actors } = await setup('g1', ['worker'])
    const started = await ledger.startThread({ requestId: requestId('g1-start'), actor: owner, workspaceId: alpha, projectRef,
