    // The owner claims the Task: it is now the executor doing the work.
    const claim = await ledger.changeClaim({ requestId: requestId('g1-claim'), actor: owner, workspaceId: alpha,
      taskRef: started.value.task!.taskRef, action: 'claim', baseRevision: started.value.thread.revision,
      direction: 'Build the gateway' })
    if (claim.value.kind !== 'committed') throw new Error('expected a committed claim')
    ctx.agentTeam['emitCommitted'](claim.value.receipt)
    seams['owner']!.calls.length = 0

    // A worker posts directly in the Thread, without mentioning the owner.
    let revision = await replyAs(ctx, started.value.thread.threadRef, claim.value.thread.revision, 4, actors['worker']!, 'g1-reply')
    console.log('GAP1 after 4 plain replies: owner notices =', seams['owner']!.calls.length)
    revision = await replyAs(ctx, started.value.thread.threadRef, revision, 1, actors['worker']!, 'g1-fifth')
    console.log('GAP1 after 5 plain replies: owner notices =', seams['owner']!.calls.length)
  })

  it('GAP 2: the accountable owner stops getting immediate delivery once the Task reaches in_review', async () => {
    const { ctx, projectRef, ledger, owner, seams, actors } = await setup('g2', ['worker'])
    const started = await ledger.startThread({ requestId: requestId('g2-start'), actor: owner, workspaceId: alpha, projectRef,
      kind: 'task', body: 'Ship the pipeline' })
    if (started.value.kind !== 'committed') throw new Error('expected a committed start')
    ctx.agentTeam['emitCommitted'](started.value.receipt)
    seams['owner']!.calls.length = 0

    const claim = await ledger.changeClaim({ requestId: requestId('g2-claim'), actor: actors['worker']!, workspaceId: alpha,
      taskRef: started.value.task!.taskRef, action: 'claim', baseRevision: started.value.thread.revision,
      direction: 'Ship the pipeline' })
    if (claim.value.kind !== 'committed') throw new Error('expected a committed claim')
    ctx.agentTeam['emitCommitted'](claim.value.receipt)
    seams['owner']!.calls.length = 0

