2760	  private deliverInboxNotice(agent: Agent, member: AgentTeamAgentMember, cause: NotificationCause, sequenced = false): void {
2761	    const notifications = this.requireLedger().notificationFacts(member.memberId)
2762	    const mainNotifications = this.requireLedger().mainNotificationFacts(member.memberId)
2763	    const scope = this.memberScope(member.memberId, agent.id)
2764	    const causeText = this.notificationCauseText(cause)
2765	    if (notifications.length === 0 && mainNotifications.length === 0) {
2766	      this.dropInboxCoverage(member.memberId)
2767	      this.ctx.logger.debug(`agent-team: Team Inbox notice not attempted for ${scope} cause ${causeText}: the Member has no unread Team facts`)
2768	      return
2769	    }
2770	    // Any ordinary next-turn input already queued (a rollover's or recovery's
2771	    // carried messages) forces sequencing regardless of the caller: a steer
2772	    // would claim the nearest step boundary and leapfrog the carried turn.
2773	    if (!sequenced) {
2774	      sequenced = agent.inbox.nextTurn.some(message => message.source.kind === 'user')
2775	    }
2776	    const previous = this.inboxNoticeDeliveries.get(member.memberId)
2777	    const plan = this.inboxDeliveryPlan(member.memberId, notifications, mainNotifications, previous)
2778	    const facts = this.notificationIdentity(notifications, mainNotifications)
2779	    // An unchanged rederivation spends no attempt: the delivery already made
2780	    // for these facts stands, which is what keeps a repeated commit's logging
2781	    // bounded.
2782	    if (plan.trigger === undefined) {
2783	      this.ctx.logger.debug(`agent-team: Team Inbox notice not attempted for ${scope} cause ${causeText}: ${plan.signature === ''
2784	        ? `only ordinary Thread updates below the threshold of ${INBOX_THRESHOLD_UPDATES} remain (${facts})`
2785	        : `the same unread facts (${facts}) already have a delivery attempt`}`)
2786	      return
2787	    }
2788	    const pending = [...agent.inbox.nextStep, ...agent.inbox.nextTurn]
2789	    // steerResume already combines the recovery instruction and these durable
2790	    // facts. Its synchronous running transition must not replace that notice.
2791	    if (pending.some(message => this.isRecoveryNotice(message))) {
2792	      this.coverInboxFacts(member.memberId, plan)
2793	      this.ctx.logger.info(`agent-team: Team Inbox notice carried by the queued recovery instruction for ${scope} cause ${causeText} (${facts}): queued with that recovery instruction, not yet read by the model`)
