2799	    const hint = createUserMessage({
2800	      content: [{ type: 'text', text: notice.text }],
2801	      source: { kind: AGENT_TEAM_PLUGIN_ID, form: 'notice', summary: TEAM_INBOX_NOTICE_SUMMARY },
2802	    })
2803	    this.trackTeamWake(agent, hint)
2804	    const recordedPlan: InboxDeliveryPlan = { ...plan, summarizedThrough: new Map([...plan.summarizedThrough].filter(([threadRef]) => notice.renderedThreads.has(threadRef))) }
2805	    const attempt = this.beginInboxDelivery(member.memberId, recordedPlan)
2806	    try {
2807	      // Steer normally claims the nearest step boundary — which would
2808	      // preempt carried input that a swap or crash recovery queued as
2809	      // ordinary next-turn messages. The sequenced mode enqueues the
2810	      // rederived Inbox as its own follow-up turn instead, so the delivery
2811	      // order stays carried input → rederived Inbox.
2812	      if (sequenced) agent.followup(hint)
2813	      else agent.steer(hint)
2814	    } catch (error) {
2815	      this.dropInboxCoverage(member.memberId, previous?.summarizedThrough ?? new Map())
2816	      if (error instanceof AgentTeamInvariantError) throw error
2817	      this.ctx.logger.warn(`agent-team: Team Inbox notice delivery failed for ${scope} cause ${causeText} attempt ${attempt} (${facts}): ${failureDetail(error)}; the operation is committed and stands, and the failed delivery stands as an attempt so the next fact touching this Member rederives and retries it`)
2818	      return
2819	    }
2820	    this.ctx.logger.info(`agent-team: Team Inbox notice queued for ${scope} cause ${causeText} attempt ${attempt} delivery ${plan.trigger} lane '${sequenced ? 'follow-up turn' : 'next step'}' (${facts}): queued for the Member's next step, not yet read by the model`)
2821	  }
