import { readFile } from 'node:fs/promises'
import { join } from 'node:path'
import type { Context } from '@deepseek-ai/cordis'
import type { PreStepDecision } from '@deepseek-ai/dsh-agent'
import { createUserMessage, type ContextFormed } from '@deepseek-ai/dsh-llm'
import { SessionLogOffset } from '@deepseek-ai/dsh-session'
import { matchesProducerKind } from './context-source.ts'
import type { AgentTeamAgentMember, AgentTeamProject } from './types.ts'
import { memberMemoryDirectoryPath } from './member-runtime.ts'

export const name = 'wowyuarm-agent-team-member-context'

/** This producer's attribution; `kind` must be producer-owned (Session format V4). The second member is the read-side rename of this producer's released V3 history. */
declare module '@deepseek-ai/dsh-llm' {
  interface MessageSourceMap {
    'wowyuarm-agent-team-member-context': { kind: 'wowyuarm-agent-team-member-context' } & ContextFormed
    'plugin:wowyuarm-agent-team-member-context': { kind: 'plugin:wowyuarm-agent-team-member-context' } & ContextFormed
  }
}

const MAX_MEMORY_BYTES = 16 * 1024
const BEGIN = '<team-member-private-memory>'
const END = '</team-member-private-memory>'

export function apply(ctx: Context): void {
  ctx.on('agent/pre-step', async ({ agent, signal }, next): Promise<PreStepDecision> => {
    const decision = await next()
    if (decision.kind === 'reject' || signal.aborted) return decision
    // The Host service is resolved at step time, never through plugin inject:
    // this row mounts while the Host itself is still restoring Members, and a
    // declared dependency on `agentTeam` would hold the preset mount open
    // until the Host service is active, failing every startup restore.
    const host = ctx.get('agentTeam')
    if (host === undefined) return decision
    const member = host.memberForAgent(agent)
    if (member === undefined) return decision
    // The sanitized path is authoritative: activation migrated any legacy
    // colon directory onto it before this member could run a step.
    const memoryPath = memberMemoryDirectoryPath(member)
    let memory: string
    try {
      memory = renderMemberMemory(await readFile(`${memoryPath}/memory.md`), memoryPath)
    } catch (error) {
      memory = renderUnavailableMemory(memoryPath, (error as NodeJS.ErrnoException).code === 'ENOENT'
        ? 'memory.md is absent; the private memory index is empty.'
        : 'memory.md is currently unreadable; do not use any earlier private memory context.')
    }
    const workspaces = renderMemberWorkspaces(host.workspacesForAgent(agent))
    const owned = host.ownedProjectsForAgent(agent)
    const ownership = owned === undefined ? '' : `\n\n${renderMemberOwnership(owned)}`
    const text = `${renderMemberIdentity(member)}${ownership}\n\n${memory}${workspaces === '' ? '' : `\n\n${workspaces}`}`
    const latestText = agent.session.surface.nodes.toReversed().flatMap(sequence => {
      // `nodes` are event identities (SessionSeq); snapshotEvents takes log
      // offsets. Re-entering through the validating constructor keeps the two
      // number domains explicit (the seq = log.length contiguity contract).
      const event = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
      return event?.type === 'user/message'
        && matchesProducerKind(event.data.source.kind, name)
        && event.data.content[0]?.type === 'text'
        ? [event.data.content[0].text]
        : []
    })[0]
    const alreadyVisible = latestText === text
    if (alreadyVisible) return decision
    const message = createUserMessage({
      content: [{ type: 'text', text }],
      source: { kind: name, form: 'instructions' },
    })
    return { kind: 'enter', messages: [...decision.messages, message] }
  }, { prepend: true })
}

export function renderMemberIdentity(member: Pick<AgentTeamAgentMember, 'handle' | 'description'>): string {
  return member.description === ''
    ? `Team identity: you are @${member.handle}.`
    : `Team identity: you are @${member.handle} — ${member.description}`
}

/** Rendered even when empty, so a withdrawn ownership replaces the earlier list instead of lingering in context. */
export function renderMemberOwnership(projects: readonly Pick<AgentTeamProject, 'projectRef' | 'name' | 'workspaceId'>[]): string {
  const header = 'Team Project ownership — this list replaces all earlier ownership context.'
  if (projects.length === 0) return `${header}\nYou own no Projects.`
  return [header, 'You own these Projects:', ...projects.map(project => `- ${project.name} ${project.projectRef} (Workspace ${project.workspaceId})`)].join('\n')
}

export function renderMemberWorkspaces(workspaces: readonly { readonly workspaceId: string; readonly path: string | undefined; readonly default: boolean }[]): string {
  if (workspaces.length <= 1) return ''
  return [
    'Team Workspace participation — this list replaces all earlier participation context.',
    ...workspaces.map(workspace => `${workspace.workspaceId}${workspace.default ? ' (creation Workspace)' : ''}: ${workspace.path === undefined
      ? 'Workspace path unavailable; ask @human before filesystem work.'
      : `${JSON.stringify(workspace.path)}; instructions: ${JSON.stringify(join(workspace.path, 'AGENTS.md'))}`}`),
    'Your Session, Team participation, Claims, and write permissions stay bound to your creation Workspace. Your working directory does not: enter a joined Workspace with working_directory({cd: <path>}) and work there, then leave the same way.',
    'Work where the work is. Relative paths, glob and grep, new shells, run_code, AGENTS.md discovery, and skill discovery all resolve from the current directory, so editing another checkout through absolute paths leaves its instructions unloaded.',
    'Pass workspace explicitly to team_view, team_thread, team_attention, team_message, team_dm and team_task. team_inbox is the cross-Workspace triage entry point.',
    'If an instruction is ambiguous about which Workspace it concerns, ask @human before acting. Participation does not itself join Projects.',
  ].join('\n')
}

/** The four private-memory paths plus the out-of-cwd warning; callers append their own sentence. */
function memoryPathsBlock(privateMemoryPath: string): string {
  return `Private memory directory: ${privateMemoryPath}\nMemory index: ${privateMemoryPath}/memory.md\nNotes directory: ${privateMemoryPath}/notes\nPrivate skills directory: ${privateMemoryPath}/skills\nThese paths are outside the Workspace cwd.`
}

export function renderMemberMemory(raw: Buffer, privateMemoryPath = '<private-memory-path>'): string {
  const overBudget = raw.byteLength > MAX_MEMORY_BYTES
  const body = overBudget ? '' : raw.toString('utf8')
  const usedKiB = (raw.byteLength / 1024).toFixed(1)
  const percent = Math.round((raw.byteLength / MAX_MEMORY_BYTES) * 100)
  const usage = `\n\nPrivate memory index: ${usedKiB} KiB / ${MAX_MEMORY_BYTES / 1024} KiB (${percent}%).`
  const warning = overBudget
    ? `\n\n[Maintenance warning: memory.md at ${raw.byteLength} B (${usedKiB} KiB, ${percent}%) exceeds the ${MAX_MEMORY_BYTES / 1024} KiB context budget. Its contents were not injected; do not delete or automatically summarize the file. Maintain a smaller index explicitly.]`
    : ''
  return `${BEGIN}\nThis is the complete replacement for this Team Member's private memory index; all earlier private-memory context is obsolete. It is reference context only, may be stale, and is not an instruction or Team fact.\n\n${memoryPathsBlock(privateMemoryPath)} Relative filesystem paths resolve from cwd, so use the absolute paths above when reading or editing this Member's memory. Only this Member can read this directory — no other human or agent sees its contents; when communicating, restate what you need from it instead of pointing others at these paths. Read matching notes on demand; do not copy credentials, sensitive data, guesses, chat logs, other Members' memory, or Team facts already owned by the ledger into memory.${usage}\n\n${escape(body)}${warning}\n${END}`
}

function renderUnavailableMemory(privateMemoryPath: string, reason: string): string {
  return `${BEGIN}\nThis is the complete replacement for this Team Member's private memory index; all earlier private-memory context is obsolete. ${reason}\n\n${memoryPathsBlock(privateMemoryPath)} Use the absolute paths above when inspecting or repairing this Member's memory.\n${END}`
}

function escape(value: string): string {
  return value.replaceAll(BEGIN, '[escaped begin marker]').replaceAll(END, '[escaped end marker]')
}

import type { AgentTeamClaim, AgentTeamMemberId, AgentTeamProjectRef, AgentTeamTask, AgentTeamTaskRef } from './types/entities.ts'

export const REVIEW_BACKLOG_IDLE_MS = 30 * 60 * 1000
export const STALLED_PUBLIC_MS = 24 * 60 * 60 * 1000
export const STALLED_IDLE_MS = 24 * 60 * 60 * 1000

export type ReminderKind = 'review-backlog' | 'stalled'

export interface ReminderClaimFacts {
  readonly claim: AgentTeamClaim
  readonly createdSequence: number
}

export interface ReminderTaskFacts {
  readonly task: AgentTeamTask
  readonly projectActive: boolean
  readonly statusBaselineSequence: number
  readonly statusBaselineOccurredAt: string
  readonly latestPublicSequence: number
  readonly latestPublicOccurredAt: string
  readonly claims: readonly ReminderClaimFacts[]
}

export interface ReminderEvaluationInput {
  readonly nowMs: number
  readonly tasks: readonly ReminderTaskFacts[]
  readonly isOwner: (projectRef: AgentTeamProjectRef, memberId: AgentTeamMemberId) => boolean
  readonly isAvailable: (memberId: AgentTeamMemberId) => boolean
  /** Milliseconds idle, or undefined when this Host has not observed a complete running → idle interval. */
  readonly idleMs: (memberId: AgentTeamMemberId) => number | undefined
  readonly heldEver: (taskRef: AgentTeamTaskRef, memberId: AgentTeamMemberId) => boolean
  readonly episodeExists: (taskRef: AgentTeamTaskRef, kind: ReminderKind, recipient: AgentTeamMemberId, baselineSequence: number) => boolean
  readonly hasUnreadResponsibility: (taskRef: AgentTeamTaskRef, recipient: AgentTeamMemberId) => boolean
}

export interface ReminderCandidate {
  readonly taskRef: AgentTeamTaskRef
  readonly kind: ReminderKind
  readonly recipient: AgentTeamMemberId
  readonly baselineSequence: number
}

export function reviewReminderRecipient(task: AgentTeamTask,
  isOwner: (projectRef: AgentTeamProjectRef, memberId: AgentTeamMemberId) => boolean,
  heldEver: (taskRef: AgentTeamTaskRef, memberId: AgentTeamMemberId) => boolean): AgentTeamMemberId {
  return task.accountable === 'member:human'
    || !isOwner(task.projectRef, task.accountable)
    || heldEver(task.taskRef, task.accountable)
    ? 'member:human' as AgentTeamMemberId : task.accountable
}

function eligible(input: ReminderEvaluationInput, candidate: ReminderCandidate): boolean {
  return !input.episodeExists(candidate.taskRef, candidate.kind, candidate.recipient, candidate.baselineSequence)
    && !input.hasUnreadResponsibility(candidate.taskRef, candidate.recipient)
}

/** Evaluate every open Task once. Unknown runtime presence never becomes an idle duration. */
export function planTaskReminders(input: ReminderEvaluationInput): readonly ReminderCandidate[] {
  const candidates: ReminderCandidate[] = []
  for (const facts of input.tasks) {
    const { task } = facts
    if (!facts.projectActive || task.resolution !== 'open') continue
    if (task.status === 'in_review') {
      const recipient = reviewReminderRecipient(task, input.isOwner, input.heldEver)
      const idleMs = input.idleMs(recipient)
      const ready = recipient === 'member:human'
        ? input.nowMs - Date.parse(facts.statusBaselineOccurredAt) >= REVIEW_BACKLOG_IDLE_MS
        : idleMs !== undefined && idleMs >= REVIEW_BACKLOG_IDLE_MS
      const candidate = { taskRef: task.taskRef, kind: 'review-backlog' as const, recipient, baselineSequence: facts.statusBaselineSequence }
      if (ready && input.isAvailable(recipient) && eligible(input, candidate)) candidates.push(candidate)
      continue
    }
    if (task.status !== 'in_progress') continue
    const activeClaims = facts.claims.filter(entry => entry.claim.state === 'active')
    const quiet = input.nowMs - Date.parse(facts.latestPublicOccurredAt) > STALLED_PUBLIC_MS
    const executorIdle = activeClaims.some(entry => {
      const idleMs = input.idleMs(entry.claim.owner)
      return idleMs !== undefined && idleMs > STALLED_IDLE_MS
    })
    const baselineSequence = Math.max(facts.latestPublicSequence, ...activeClaims.map(entry => entry.createdSequence))
    const candidate = { taskRef: task.taskRef, kind: 'stalled' as const, recipient: task.accountable, baselineSequence }
    if ((quiet || executorIdle) && input.isAvailable(task.accountable) && eligible(input, candidate)) candidates.push(candidate)
  }
  return candidates
}

readMainStream(request: AgentTeamAuthorizedMainStreamReadRequest): Promise<AgentTeamLedgerResult<AgentTeamMainStreamReadResult>> {
  return this.enqueue(async () => {
    const actor = this.assertActorForWorkspace(request.actor, request.workspaceId)
    const project = this.requireActiveProject(request.workspaceId, request.projectRef)
    const existing = this.state.byRequest.get(request.requestId)
    if (existing !== undefined) {
      this.assertSameMainRead(existing, request, project.projectRef)
      return this.resolved(this.mainReadResult(actor.memberId, project.projectRef, existing.data.readThroughSequence, [], this.receipt(existing)))
    }
    this.requireRulesVersion2('the Main stream')
    this.requireProjectMemberActor(actor, project.projectRef)
    const head = this.mainHeadFrom(this.state, project.projectRef)
    // Without an explicit bound a read acknowledges only the first page of unread, so a backlog is read page by page, never skipped.
    const backlog = request.readThroughSequence === undefined ? this.mainUnreadFrom(this.state, actor.memberId, project.projectRef) : []
    const readThrough = request.readThroughSequence ?? (backlog.length > MAIN_READ_PAGE_SIZE ? backlog[MAIN_READ_PAGE_SIZE - 1]!.source.sequence : head)
    if (!Number.isInteger(readThrough) || readThrough < 0 || readThrough > head) {
      throw new Error(`readThroughSequence must be an integer from 0 to the Main stream head ${head}`)
    }
    const prepared = this.prepareMainReadFrom(this.state, actor.memberId, project.projectRef, readThrough)
    if (!prepared.advances && isEmptyInboxDelta(prepared.inbox)) {
      return this.resolved(this.mainReadResult(actor.memberId, project.projectRef, readThrough, []))
    }
    const operation: AgentTeamMainStreamReadOperation = Object.freeze({
      ...this.operationBase(request, this.nextSequence()), kind: 'team/main-stream-read',
      data: Object.freeze({ workspaceId: request.workspaceId, projectRef: project.projectRef, memberId: actor.memberId,
        readThroughSequence: readThrough, inbox: prepared.inbox }),
    })
    // The picture shows what the reader saw before this read, so it is taken ahead of the commit.
    const picture = this.mainReadPage(actor.memberId, project.projectRef, prepared.consumed, readThrough)
    await this.table.put(operation.operationId, operation)
    this.applyAndAdvanceProjectionVersion(operation)
    return this.committed(Object.freeze({ receipt: this.receipt(operation), projectRef: project.projectRef, readThroughSequence: readThrough,
      entries: picture, consumedMarkers: prepared.consumed, standing: this.mainStandingFrom(this.state, actor.memberId, project.projectRef) }))
  })
}

/** Start a discussion or Task Thread: a Project owner's act. Mentions deliver a direct marker only; the creator alone follows. */
startThread(request: AgentTeamAuthorizedStartThreadRequest): Promise<AgentTeamLedgerResult<AgentTeamStartThreadResult>> {
  return this.enqueue(async () => {
    const actor = this.assertActorForWorkspace(request.actor, request.workspaceId)
    const project = this.requireActiveProject(request.workspaceId, request.projectRef)
    const body = request.body.trim()
    if (body === '') throw new Error('message body must not be empty')
    const recipients = this.mergeBodyMentions(actor.memberId, project.projectRef, body, [])
    const existing = this.state.byRequest.get(request.requestId)
    if (existing !== undefined) {
      this.assertSameThreadStart(existing, request, recipients)
      return this.resolved(this.startThreadResult(existing))
    }
    this.requireRulesVersion2('starting a Thread')
    this.requireProjectMemberActor(actor, project.projectRef)
    this.requireProjectOwnerActor(actor, project.projectRef)
    this.assertMentionTargets(project, recipients)
    const sequence = this.nextSequence()
    const base = this.operationBase(request, sequence)
    const threadRef = this.ref('thread')
    const taskRef = request.kind === 'task' ? this.ref('task') : undefined
    if (request.kind === 'task' && actor.kind === 'member' && request.accountable !== undefined && request.accountable !== actor.memberId) {
      throw new Error(`An Agent names itself accountable when starting a Task (accountable_target_invalid) — ${recoveryFor('accountable_target_invalid').sentence({})}`)
    }
    const accountable = request.kind === 'task' ? this.resolveAccountable(project.projectRef, actor, request.accountable) : undefined
    if (request.kind !== 'task' && (request.accountable !== undefined || request.sourceThreadRefs !== undefined)) throw new Error('only a Task accepts accountable and sourceThreadRefs')
    const sourceThreadRefs = request.kind === 'task' ? this.validateTaskSources(project.projectRef, request.sourceThreadRefs) : []
    const task = taskRef === undefined || accountable === undefined ? undefined
      : Object.freeze({ taskRef, projectRef: project.projectRef, threadRef, status: 'todo' as const, resolution: 'open' as const, accountable, sourceThreadRefs })
    const taskActivity = task === undefined ? undefined : Object.freeze({ activityRef: this.ref('activity'), kind: 'promote' as const,
      taskRef: task.taskRef, threadRef, actor: actor.memberId, sequence })
    const thread: AgentTeamThread = Object.freeze({ threadRef, ...(taskRef === undefined ? {} : { taskRef }), revision: sequence })
    const anchor: AgentTeamMessage = Object.freeze({
      messageRef: this.ref('message'), projectRef: project.projectRef, threadRef, ...(taskRef === undefined ? {} : { taskRef }),
      sender: actor.memberId, body,
      ...(request.resolvedAttachments === undefined ? {} : { attachments: request.resolvedAttachments }),
      topLevel: true, sequence, occurredAt: base.occurredAt,
    })
    const inbox = taskActivity === undefined
      ? this.messageInboxDelta(anchor, actor.memberId, recipients, [this.startAttention(actor.memberId, threadRef, sequence)])
      : this.inboxDeltaForTaskResponsibility(this.state, task!, taskActivity, anchor, recipients)
    const operation: AgentTeamThreadStartedOperation = Object.freeze({
      ...base, kind: 'team/thread-started',
      data: Object.freeze({ workspaceId: request.workspaceId, projectRef: project.projectRef, kind: request.kind, mentions: recipients,
        anchor, ...(task === undefined ? {} : { task }), ...(taskActivity === undefined ? {} : { activity: taskActivity }), thread, inbox }),
    })
    await this.table.put(operation.operationId, operation)
    this.applyAndAdvanceProjectionVersion(operation)
    return this.committed(this.startThreadResult(operation))
  })
}

/** One page of a Project's Main stream, oldest first, with the reader's own standing. Never writes. */
mainStreamHistory(actor: AgentTeamHumanActor | AgentTeamMemberActor, request: AgentTeamMainStreamHistoryRequest): AgentTeamMainStreamHistory {
  this.requireRulesVersion2('the Main stream')
  const authorized = this.assertActorForWorkspace(actor, request.workspaceId)
  const project = this.requireActiveProject(request.workspaceId, request.projectRef)
  this.requireProjectMemberActor(authorized, project.projectRef)
  const limit = request.limit ?? 20
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error('history limit must be an integer between 1 and 100')
  const sources = this.mainSourcesFrom(this.state, project.projectRef).filter(source => source.kind !== 'thread' || source.hidden !== true)
  const before = request.beforeSequence ?? (sources.at(-1)?.sequence ?? 0) + 1
  if (!Number.isInteger(before) || before < 1) throw new Error('beforeSequence must be a positive integer')
  const older = sources.filter(source => source.sequence < before)
  const page = older.slice(-limit)
  const unread = this.mainUnreadFrom(this.state, authorized.memberId, project.projectRef)
  return Object.freeze({ projectRef: project.projectRef, entries: this.mainEntries(page, unread),
    cursor: page.length === 0 ? before : page[0]!.sequence, hasMore: older.length > page.length,
    standing: this.mainStandingFrom(this.state, authorized.memberId, project.projectRef) })
}

/** One Member's unread Main stream entries, per Project, for the Host's wake: an owner's ordinary unread and every reader's markers. */
mainNotificationFacts(memberId: AgentTeamMemberId): readonly { readonly project: AgentTeamProject; readonly entries: readonly AgentTeamMainTimelineEntry[] }[] {
  const result: { project: AgentTeamProject; entries: readonly AgentTeamMainTimelineEntry[] }[] = []
  for (const project of this.state.projects.values()) {
    if (this.visibleProject(project) === undefined || !this.participatesIn(memberId, project.workspaceId)) continue
    const unread = this.mainUnreadFrom(this.state, memberId, project.projectRef)
    if (unread.length > 0) result.push({ project, entries: this.mainEntries(unread.map(item => item.source), unread) })
  }
  return Object.freeze(result)
}

promoteThread(request: AgentTeamAuthorizedPromoteThreadRequest): Promise<AgentTeamLedgerResult<AgentTeamPromoteThreadResult>> {
  return this.enqueue(async () => {
    const existing = this.state.byRequest.get(request.requestId)
    if (existing !== undefined) {
      this.assertSamePromotion(existing, request)
      return this.resolved(this.promotionResult(existing))
    }
    const v2 = this.state.rulesVersion >= 2
    if (v2 && request.actor.kind === 'member') this.assertMemberActor(request.actor)
    else this.assertHumanActor(request.actor)
    const { task: existingTask, thread, projectRef } = this.threadContextForActor(request.actor, request.workspaceId, request)
    if (v2) this.requireProjectOwnerActor(request.actor, projectRef)
    if (existingTask !== undefined) throw new Error(`Thread '${thread.threadRef}' already has Task '${existingTask.taskRef}'`)
    const deferred = this.deferredThreadWrite(request.actor.memberId, undefined, thread, request.baseRevision)
    if (deferred !== undefined) return this.resolved(deferred)
    const sequence = this.nextSequence()
    const base = this.operationBase(request, sequence)
    const taskRef = this.ref('task')
    if (request.actor.kind === 'member' && request.accountable !== undefined && request.accountable !== request.actor.memberId) {
      throw new Error(`An Agent names itself accountable when promoting a Task (accountable_target_invalid) — ${recoveryFor('accountable_target_invalid').sentence({})}`)
    }
    const accountable = this.resolveAccountable(projectRef, request.actor, request.accountable)
    const task: AgentTeamTask = Object.freeze({ taskRef, projectRef, threadRef: thread.threadRef, status: 'todo', resolution: 'open', accountable, sourceThreadRefs: [] })
    const nextThread: AgentTeamThread = Object.freeze({ threadRef: thread.threadRef, taskRef, revision: sequence })
    const activity: AgentTeamTaskActivity = Object.freeze({ activityRef: this.ref('activity'), kind: 'promote',
      taskRef, threadRef: thread.threadRef, actor: request.actor.memberId, sequence })
    const inbox = this.state.rulesVersion >= 2
      ? this.responsibilityInboxDeltaFrom(this.state, task, activity, request.actor.memberId, true)
      : this.promoteThreadInbox(activity, thread.threadRef)
    const operation: AgentTeamThreadPromotedOperation = Object.freeze({
      ...base, kind: 'team/thread-promoted',
      data: Object.freeze({ workspaceId: request.workspaceId, baseRevision: request.baseRevision,
        activity, task, thread: nextThread, inbox }),
    })
    await this.table.put(operation.operationId, operation)
    this.applyAndAdvanceProjectionVersion(operation)
    return this.committed(this.promotionResult(operation))
  })
}

changeClaim(request: AgentTeamAuthorizedClaimRequest): Promise<AgentTeamLedgerResult<AgentTeamClaimResult>> {
  return this.enqueue(async () => {
    const existing = this.state.byRequest.get(request.requestId)
    if (existing !== undefined) {
      this.assertSameClaim(existing, request)
      return this.resolved(this.claimResult(existing))
    }
    const actor = this.assertActorForWorkspace(request.actor, request.workspaceId)
    const { task, thread } = this.threadForActor(actor, request.workspaceId, request.taskRef)
    const deferred = this.deferredThreadWrite(actor.memberId, task, thread, request.baseRevision)
    if (deferred !== undefined) return this.resolved(deferred)
    if (task.resolution !== 'open') throw new Error(`Task '${task.taskRef}' is ${task.status}; reopen it before changing Claims`)
    if (actor.kind !== 'member') throw new Error('Human cannot change an Agent Claim')
    let claim: AgentTeamClaim
    let kind: AgentTeamClaimChangedOperation['kind']
    let activityKind: AgentTeamClaimActivity['kind']
    if (request.action === 'claim') {
      if (request.claimRef !== undefined) throw new Error('claim action does not accept claimRef')
      const direction = request.direction?.trim() ?? ''
      const normalizedDirection = this.normalizeDirection(direction)
      if (normalizedDirection === '') throw new Error('claim direction must not be empty')
      if ((this.state.claimsByTask.get(task.taskRef) ?? []).some(candidate =>
        candidate.state === 'active' && candidate.normalizedDirection === normalizedDirection)) {
        throw new Error(`Direction '${direction}' already has an active Claim`)
      }
      claim = Object.freeze({ claimRef: this.ref('claim'), taskRef: task.taskRef, threadRef: task.threadRef,
        owner: actor.memberId, direction, normalizedDirection, state: 'active' })
      kind = 'team/claim-created'
      activityKind = 'claim'
    } else {
      if (request.direction !== undefined) throw new Error(`${request.action} action does not accept direction`)
      const previous = request.claimRef === undefined ? undefined : this.state.claims.get(this.requireRefKey(this.state.claims, request.claimRef, 'claim', 'Claim'))
      if (previous === undefined) {
        throw new Error(`unknown Claim '${request.claimRef ?? ''}'${request.claimRef === undefined ? '' : this.unknownRefHint(request.claimRef, 'claim', 'Claim')}`)
      }
      if (previous.taskRef !== task.taskRef || previous.owner !== actor.memberId) {
        throw new Error(`Member can modify only its own Claim on this Task — ${recoveryFor('claim_owned_by_another').sentence({ refused: `claim ${previous.claimRef}` })}`)
      }
      if (previous.state !== 'active') throw new Error(`Claim '${previous.claimRef}' is already ${previous.state}`)
      claim = Object.freeze({ ...previous, state: request.action === 'done' ? 'done' : 'released' })
      kind = request.action === 'done' ? 'team/claim-done' : 'team/claim-released'
      activityKind = request.action

